import {publicURL} from './osint-core.mjs';
export const MEDIA_TOPICS=Object.freeze({flood:'Floods',wildfire:'Wildfires',hurricane:'Storms',volcano:'Volcanic events',earthquake:'Earthquakes'});
export function nasaAssetURL(value){let parsed;try{parsed=new URL(value);}catch{return null;}if(parsed.hostname!=='images-assets.nasa.gov'||parsed.port||parsed.username||parsed.password)return null;if(parsed.protocol==='http:')parsed.protocol='https:';return publicURL(parsed.href);}
export function mediaSearchURL(topic,type='image'){if(!Object.hasOwn(MEDIA_TOPICS,topic)||!['image','video'].includes(type))throw new Error('Choose a configured media topic and type.');return `https://images-api.nasa.gov/search?${new URLSearchParams({q:topic,media_type:type,page_size:'12'})}`;}
export function parseMediaSearch(payload){if(!Array.isArray(payload?.collection?.items)||payload.collection.items.length>100)throw new Error('Invalid NASA search response.');const items=[];
  for(const item of payload.collection.items){const d=item?.data?.[0];if(!d||typeof d.nasa_id!=='string'||!/^[a-zA-Z0-9_. -]{1,180}$/.test(d.nasa_id)||!['image','video'].includes(d.media_type)||typeof d.title!=='string'||d.title.length>500)continue;
    const links=Array.isArray(item.links)?item.links:[],preview=links.find(l=>l?.render==='image'&&/~small\./.test(l.href??'')&&nasaAssetURL(l.href))??links.find(l=>l?.rel==='preview'&&nasaAssetURL(l.href));
    if(!preview)continue;items.push({id:d.nasa_id,title:d.title,type:d.media_type,date:typeof d.date_created==='string'?d.date_created.slice(0,40):'Unknown',description:typeof d.description==='string'?d.description.slice(0,3000):'',credit:String(d.secondary_creator??d.center??'NASA').slice(0,300),preview:nasaAssetURL(preview.href),sourceURL:`https://images.nasa.gov/details/${encodeURIComponent(d.nasa_id)}`});
  }return items.slice(0,12);
}
export async function mediaJSON(url,fetchImpl=fetch){const r=await fetchImpl(url,{credentials:'omit',referrerPolicy:'no-referrer',redirect:'error',signal:AbortSignal.timeout(20000)});if(!r.ok)throw new Error(`Media source returned HTTP ${r.status}.`);if(!/^application\/json/i.test(r.headers.get('content-type')??''))throw new Error('Media source did not return JSON.');const reader=r.body.getReader();let raw='',size=0;const decoder=new TextDecoder();try{while(true){const {value,done}=await reader.read();if(done)break;size+=value.byteLength;if(size>2000000)throw new Error('Media catalog response exceeds 2 MB.');raw+=decoder.decode(value,{stream:true});}return JSON.parse(raw+decoder.decode());}finally{try{await reader.cancel();}catch{}reader.releaseLock();}}
export function selectVideoAsset(payload){const urls=payload?.collection?.items?.map(i=>nasaAssetURL(i?.href)).filter(Boolean)??[];return urls.find(u=>/~small\.mp4$/i.test(u))??urls.find(u=>/~mobile\.mp4$/i.test(u))??null;}
export function validateMediaDraft(value,frameIds){if(!value||!Array.isArray(value.observations)||value.observations.length>15||!Array.isArray(value.limitations)||value.limitations.length>12)throw new Error('Invalid media analysis result.');for(const row of value.observations)if(!frameIds.includes(row.frameId)||typeof row.description!=='string'||row.description.length>1200||!['low','medium','high'].includes(row.confidence))throw new Error('Invalid frame citation in model output.');if(value.limitations.some(s=>typeof s!=='string'||s.length>1500))throw new Error('Invalid media limitations.');return value;}
